`src/envs/dev/infra/logs.ts`
```typescript
import {
  ReaderIam,
  SecureBucket,
} from "../../../composites/index.js";

const ENV = "dev";
const REGION = "us-east-1";

// ── Application logs bucket ──────────────────────────────────────────────────
// Versioned + encrypted logs bucket.

export const logs = SecureBucket({
  name: "myapp-logs-dev",
  env: ENV,
  region: REGION,
  component: "logs",
});

// ── Logs reader identity ─────────────────────────────────────────────────────
// Service account with read + write access to the logs bucket only.

export const logsReader = ReaderIam({
  name: "myapp-dev-logs",
  env: ENV,
  bucketName: "myapp-logs-dev",
  trust: { mode: "account", accountID: "123456789012" },
  additionalActions: ["s3:PutObject"],
  programmaticAccess: true,
  component: "logs",
});
```

`src/envs/prod/infra/logs.ts`
```typescript
import {
  ReaderIam,
  SecureBucket,
} from "../../../composites/index.js";

const ENV = "prod";
const REGION = "us-east-1";
const APP_NAMESPACE = "app";
const SERVICE_ACCOUNT = "myapp";

// ── Application logs bucket ──────────────────────────────────────────────────
// Versioned + encrypted logs bucket.

export const logs = SecureBucket({
  name: "myapp-logs-prod",
  env: ENV,
  region: REGION,
  component: "logs",
});

// ── Logs reader identity ─────────────────────────────────────────────────────
// Service account with read + write access to the logs bucket only.

export const logsReader = ReaderIam({
  name: "myapp-prod-logs",
  env: ENV,
  bucketName: "myapp-logs-prod",
  trust: {
    mode: "oidc",
    providerARN: "arn:aws:iam::123456789012:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/EXAMPLEPROD",
    issuerHost: "oidc.eks.us-east-1.amazonaws.com/id/EXAMPLEPROD",
    serviceAccountNamespace: APP_NAMESPACE,
    serviceAccountName: SERVICE_ACCOUNT,
  },
  additionalActions: ["s3:PutObject"],
  programmaticAccess: false,
  podIdentity: {
    clusterName: "myapp-prod",
    serviceAccountNamespace: APP_NAMESPACE,
    serviceAccountName: SERVICE_ACCOUNT,
  },
  component: "logs",
});
```

Both files export the new bucket and reader identity independently, following the existing pattern. The `chant build` discovery will automatically pick up these files alongside the existing `main.ts` in each `infra/` directory. Each `logsReader` grants exactly `s3:GetObject` (from `ReaderIam`'s baseline) plus the explicitly enumerated `s3:PutObject` via `additionalActions`, with no wildcard actions or resources. The trust configuration matches the respective environment's existing pattern: account-mode in dev, OIDC with pinned subject and audience in prod.
